mapper.select:
SELECT DATE(wr.timestamp) AS statDate, wm.id AS meterId, wm.customer_id AS merchantId, c.customer_name AS merchantName, COALESCE(NULLIF(wm.meteraddress, ''), wm.steal_no) AS deviceNo, COALESCE(SUM(COALESCE(wr.read_val, wr.data_value0, wr.kwh)), 0) AS totalUsage, 0 AS totalFee FROM t_meter_reading wr INNER JOIN t_meter wm ON wr.meter_id = wm.id AND (wm.meter_type = 0 OR (wm.meter_type IS NULL AND wm.meteraddress IS NOT NULL AND wm.meteraddress != '')) AND wm.is_deleted = 0 LEFT JOIN t_customer c ON wm.customer_id = c.id
WHERE 1=1
AND wr.timestamp >= #{startDate}
AND wr.timestamp < #{endDate}
AND wm.customer_id = #{merchantId}
AND c.customer_name LIKE CONCAT('%', #{merchantName}, '%')
AND wm.meteraddress = #{deviceNo}
GROUP BY DATE(wr.timestamp), wm.id, wm.customer_id, c.customer_name, wm.meteraddress
ORDER BY statDate DESC, totalUsage DESC

SELECT DATE(wr.timestamp) AS statDate, COALESCE(SUM(COALESCE(wr.read_val, wr.data_value0, wr.kwh)), 0) AS totalUsage, 0 AS totalFee, COUNT(DISTINCT wr.meter_id) AS meterCount FROM t_meter_reading wr INNER JOIN t_meter wm ON wr.meter_id = wm.id AND (wm.meter_type = 0 OR (wm.meter_type IS NULL AND wm.meteraddress IS NOT NULL AND wm.meteraddress != '')) AND wm.is_deleted = 0
WHERE 1=1
AND wr.timestamp >= #{startDate}
AND wr.timestamp < #{endDate}
AND wm.customer_id = #{merchantId}
AND wm.meteraddress = #{deviceNo}
GROUP BY DATE(wr.timestamp) ORDER BY statDate DESC

SELECT DATE_FORMAT(wr.timestamp, '%Y-%m') AS statMonth, wm.id AS meterId, wm.customer_id AS merchantId, c.customer_name AS merchantName, COALESCE(NULLIF(wm.meteraddress, ''), wm.steal_no) AS deviceNo, COALESCE(SUM(COALESCE(wr.read_val, wr.data_value0, wr.kwh)), 0) AS totalUsage, 0 AS totalFee, COUNT(DISTINCT DATE(wr.timestamp)) AS dailyCount FROM t_meter_reading wr INNER JOIN t_meter wm ON wr.meter_id = wm.id AND (wm.meter_type = 0 OR (wm.meter_type IS NULL AND wm.meteraddress IS NOT NULL AND wm.meteraddress != '')) AND wm.is_deleted = 0 LEFT JOIN t_customer c ON wm.customer_id = c.id
WHERE 1=1
AND DATE_FORMAT(wr.timestamp, '%Y-%m') = #{statMonth}
AND DATE_FORMAT(wr.timestamp, '%Y') = #{statYear}
AND wm.customer_id = #{merchantId}
AND c.customer_name LIKE CONCAT('%', #{merchantName}, '%')
AND wm.meteraddress = #{deviceNo}
GROUP BY DATE_FORMAT(wr.timestamp, '%Y-%m'), wm.id, wm.customer_id, c.customer_name, wm.meteraddress
ORDER BY statMonth DESC, totalUsage DESC

SELECT DATE_FORMAT(wr.timestamp, '%Y-%m') AS statMonth, COALESCE(SUM(COALESCE(wr.read_val, wr.data_value0, wr.kwh)), 0) AS totalUsage, 0 AS totalFee, COUNT(DISTINCT wr.meter_id) AS meterCount, COUNT(DISTINCT DATE(wr.timestamp)) AS dailyCount FROM t_meter_reading wr INNER JOIN t_meter wm ON wr.meter_id = wm.id AND (wm.meter_type = 0 OR (wm.meter_type IS NULL AND wm.meteraddress IS NOT NULL AND wm.meteraddress != '')) AND wm.is_deleted = 0
WHERE 1=1
AND DATE_FORMAT(wr.timestamp, '%Y-%m') = #{statMonth}
AND wm.customer_id = #{merchantId}
AND wm.meteraddress = #{deviceNo}
GROUP BY DATE_FORMAT(wr.timestamp, '%Y-%m') ORDER BY statMonth DESC

SELECT DATE_FORMAT(wr.timestamp, '%Y-%m') AS statMonth, wm.id AS meterId, wm.customer_id AS merchantId, c.customer_name AS merchantName, COALESCE(NULLIF(wm.meteraddress, ''), wm.steal_no) AS deviceNo, COALESCE(SUM(COALESCE(wr.read_val, wr.data_value0, wr.kwh)), 0) AS totalUsage, 0 AS totalFee, COUNT(DISTINCT DATE(wr.timestamp)) AS dailyCount, DATE(wm.update_time) AS deletedTime, 'READING' AS dataSource FROM t_meter_reading wr INNER JOIN t_meter wm ON wr.meter_id = wm.id AND wm.is_deleted = 1 LEFT JOIN t_customer c ON wm.customer_id = c.id
WHERE 1=1
AND DATE_FORMAT(wr.timestamp, '%Y-%m') = #{statMonth}
AND wm.customer_id = #{merchantId}
AND c.customer_name LIKE CONCAT('%', #{merchantName}, '%')
AND wm.meteraddress = #{deviceNo}
GROUP BY DATE_FORMAT(wr.timestamp, '%Y-%m'), wm.id, wm.customer_id, c.customer_name, wm.meteraddress, DATE(wm.update_time)
ORDER BY statMonth DESC, totalUsage DESC

SELECT DATE_FORMAT(wr.timestamp, '%Y-%m') AS statMonth, COALESCE(SUM(COALESCE(wr.read_val, wr.data_value0, wr.kwh)), 0) AS totalUsage, 0 AS totalFee, COUNT(DISTINCT wr.meter_id) AS meterCount, COUNT(DISTINCT DATE(wr.timestamp)) AS dailyCount FROM t_meter_reading wr INNER JOIN t_meter wm ON wr.meter_id = wm.id AND (wm.meter_type = 0 OR (wm.meter_type IS NULL AND wm.meteraddress IS NOT NULL AND wm.meteraddress != '')) AND wm.is_deleted = 0
