SELECT DATE(wr.timestamp) AS statDate, COALESCE(SUM(COALESCE(wr.read_val, wr.data_value0, wr.kwh)), 0) AS totalUsage, 0 AS totalFee, COUNT(DISTINCT wr.meter_id) AS meterCount FROM t_meter_reading wr INNER JOIN t_meter wm ON wr.meter_id = wm.id AND (wm.meter_type = 0 OR (wm.meter_type IS NULL AND wm.meteraddress IS NOT NULL AND wm.meteraddress != '')) AND wm.is_deleted = 0
